#!/usr/bin/env python3
"""Generate typed current Swift DTOs and normalized inventory from pinned public sources."""
import json
import subprocess
from pathlib import Path
ROOT=Path(__file__).resolve().parents[2]
evidence=json.loads((ROOT/'catalog/evidence/swift-current-sources.json').read_text())
# Models are explicit SDK-owned mappings of the pinned Selectel headers and
# compatible OpenStack JSON rows. No protocol-specific raw executor is public.
models={
 'BucketEntry':{'Name':'*string','Count':'*types.Integer','Bytes':'*types.Integer','LastModified':'*string','Ref':'*types.ResourceRef'},
 'ObjectEntry':{'Name':'*string','Subdir':'*string','Bytes':'*types.Integer','Hash':'*string','ContentType':'*types.ProtectedValue','LastModified':'*string','Ref':'*types.ResourceRef'},
 'BulkResult':{'NumberDeleted':'*types.Integer','NumberNotFound':'*types.Integer','ResponseStatus':'*types.ProtectedValue','ResponseBody':'*types.ProtectedValue','Errors':'[]BulkError'},
 'BulkError':{'Path':'types.ProtectedValue','Detail':'types.ProtectedValue'},
 'Segment':{'Object':'types.ResourceRef','ETag':'*string','SizeBytes':'*types.Integer'},
 'StoragePolicyUsage':{'BytesUsed':'*types.Integer','ContainerCount':'*types.Integer','ObjectCount':'*types.Integer'},
 'AccountInfo':{'Ref':'*types.ResourceRef','BytesUsed':'*types.Integer','ContainerCount':'*types.Integer','ObjectCount':'*types.Integer','Created':'*types.Number','Metadata':'map[string]types.ProtectedValue','StoragePolicies':'map[string]StoragePolicyUsage','QuotaBytes':'*types.Integer'},
 'BucketInfo':{'Ref':'*types.ResourceRef','BytesUsed':'*types.Integer','ObjectCount':'*types.Integer','Created':'*types.Number','Metadata':'map[string]types.ProtectedValue','QuotaBytes':'*types.Integer','QuotaCount':'*types.Integer','DefaultDeleteAfter':'*types.Integer','Type':'*string','VersionsEnabled':'*bool','StoragePolicyName':'*string','StoragePolicyIndex':'*types.Integer'},
 'ObjectInfo':{'Ref':'*types.ResourceRef','ContentLength':'*types.Integer','ETag':'*string','LastModifiedRaw':'*string','ContentType':'*types.ProtectedValue','ContentEncoding':'*types.ProtectedValue','ContentDisposition':'*types.ProtectedValue','CacheControl':'*types.ProtectedValue','Link':'*types.ProtectedValue','Metadata':'map[string]types.ProtectedValue','Created':'*types.Number','DeleteAt':'*types.Integer','Manifest':'*types.ProtectedValue','StaticLargeObject':'*bool','SymlinkTarget':'*types.ProtectedValue','SymlinkTargetETag':'*string','CopiedFrom':'*types.ProtectedValue','CopiedFromLastModifiedRaw':'*string'},
 'MetadataUpdate':{'Set':'map[string]types.ProtectedValue','Remove':'[]string'},
 'AccountUpdate':{'Metadata':'MetadataUpdate','QuotaBytes':'*types.Integer'},
 'BucketCreate':{'Metadata':'map[string]types.ProtectedValue','Type':'*string','StoragePolicy':'*string','VersionsEnabled':'*bool','DefaultDeleteAfter':'*types.Integer'},
 'BucketUpdate':{'Metadata':'MetadataUpdate','Type':'*string','VersionsEnabled':'*bool','QuotaBytes':'*types.Integer','QuotaCount':'*types.Integer','DefaultDeleteAfter':'*types.Integer'},
 'ObjectUpdate':{'Metadata':'map[string]types.ProtectedValue','CacheControl':'*types.ProtectedValue','ContentEncoding':'*types.ProtectedValue','ContentType':'*types.ProtectedValue','ContentDisposition':'*types.ProtectedValue','Link':'*types.ProtectedValue','DeleteAt':'*types.Integer','DeleteAfter':'*types.Integer'},
 'CopyOptions':{'FreshMetadata':'*bool','Metadata':'map[string]types.ProtectedValue'},
 'UploadOptions':{'Metadata':'map[string]types.ProtectedValue','ContentType':'*types.ProtectedValue','ETag':'*string','DeleteAt':'*types.Integer','DeleteAfter':'*types.Integer'},
 'DownloadOptions':{'MaxBytes':'int64','Manifest':'bool','Symlink':'bool'},
 'Transfer':{'Object':'ObjectInfo','Bytes':'int64','Complete':'bool'},
}
def snake(s):
 import re
 return re.sub(r'(?<!^)(?=[A-Z][a-z])','_',s).lower()
lines=['// Code generated by internal/swiftgen/generate.py; DO NOT EDIT.','// Sources: pinned Selectel Swift current page, headers and compatible OpenStack wire shapes.','package swift','','import "github.com/festy23/selectel-sdk/types"', 'import "github.com/festy23/selectel-sdk/pagination"','']
for name,fields in models.items():
 lines.append('type '+name+' struct {')
 for field,typ in fields.items():wire={'LastModified':'last_modified','ContentType':'content_type','ETag':'etag','SymlinkTargetETag':'symlink_target_etag'}.get(field,snake(field)); lines.append(field+' '+typ+' `json:"'+wire+',omitempty"`')
 lines.append('}\n')
lines.append('type Listing[T, H any] struct { pagination.Collection[T]; HeaderPages []H `json:"header_pages,omitempty"` }')
lines.append('type ListOptions struct { Marker, Prefix, Delimiter *string }')
(ROOT/'swift/types_generated.go').write_text('\n'.join(lines))
ops=[('HEAD','/v1/{project_id}','account.get',[204]),('GET','/v1/{project_id}','buckets.list',[200,204]),('POST','/v1/{project_id}','account.update',[204,202]),('HEAD','/v1/{project_id}/{bucket_name}','buckets.get',[204]),('GET','/v1/{project_id}/{bucket_name}','objects.list',[200,204]),('PUT','/v1/{project_id}/{bucket_name}','buckets.create',[201]),('POST','/v1/{project_id}/{bucket_name}','buckets.update',[204,202]),('DELETE','/v1/{project_id}/{bucket_name}','buckets.delete',[204]),('GET','/v1/{project_id}/{bucket_name}/{object_name}','objects.get',[200]),('HEAD','/v1/{project_id}/{bucket_name}/{object_name}','objects.head_symlink',[200]),('PUT','/v1/{project_id}/{bucket_name}/{object_name}','objects.put',[201]),('POST','/v1/{project_id}/{bucket_name}/{object_name}','objects.update',[201,202]),('COPY','/v1/{project_id}/{bucket_name}/{object_name}','objects.copy',[201]),('DELETE','/v1/{project_id}/{bucket_name}/{object_name}','objects.delete',[204]),('POST','/$bulk-delete','objects.bulk_delete',[200])]
source={'x-source-uri':'https://docs.selectel.ru/api/object-storage-swift/','x-inventory-kind':'Confirmed current Selectel Swift subset; normalized bulk query selector; headers/query variants share primitive binding, inventory completeness unknown','x-pinned-evidence':[{'uri':d['uri'],'sha256':d['sha256']} for d in evidence['documents']],'x-disposition':evidence['disposition'],'paths':{}}
for method,path,tail,statuses in ops:
 source['paths'].setdefault(path,{})[method.lower()]={'x-effect':'read' if method in ['GET','HEAD'] else 'mutation','x-operation-id':'swift.v1.'+tail,'x-operation-locator':method+' '+(path if path!='/'+ '$bulk-delete' else '/v1/{project_id}?bulk-delete=true&format=json'),'responses':{str(status):{'typed':True} for status in statuses}}
(ROOT/'catalog/sources/swift-current.json').write_text(json.dumps(source,indent=2)+'\n')
subprocess.run(['gofmt','-w',str(ROOT/'swift/types_generated.go')],check=True)
